function persist(){try{localStorage.setItem(KEY,JSON.stringify({language:state.language,words:state.words,custom:state.custom,bookmarks:state.bookmarks,read:state.read,activity:state.activity}))}catch{toast('Browser storage is full. Export your words to keep a backup.')}}
function activity(){const day=new Date().toISOString().slice(0,10);if(!state.activity.includes(day))state.activity.push(day);persist()}
